const PHONE_NUMBER_ID = '1243456698857049';

const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const to = String(b.to || '967773590979').replace(/[^0-9]/g, '');
  const text = String(b.text || 'إشعار جديد من تطبيق ACTES');
  const rawButtons = Array.isArray(b.buttons) && b.buttons.length
    ? b.buttons
    : [
        { id: 'invoice_confirm', title: '✅ تأكيد الفاتورة' },
        { id: 'invoice_cancel', title: '❌ إلغاء الفاتورة' },
      ];
  const buttons = rawButtons.slice(0, 3).map((btn) => ({
    type: 'reply',
    reply: {
      id: String(btn.id).slice(0, 256),
      title: String(btn.title).slice(0, 20),
    },
  }));

  out.push({
    json: {
      phoneNumberId: PHONE_NUMBER_ID,
      payload: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: { text: text.slice(0, 1024) },
          action: { buttons },
        },
      },
    },
  });
}
return out;
